I tested it only on Safari for macOS earlier, then tested it again on an iPhone just now with your JavaScript rule. Unfortunately, it doesn't work 😕

```adblock
decrypt.day#@#div[class] > center:has(> div.w-full > ins.adsbygoogle)
decrypt.day#@$#div[class] > center:has(> div.w-full > ins.adsbygoogle) { display: block !important; position: absolute !important; left: -9999px !important; }
decrypt.day#%#!function(){var t,e=!1;function o(){if(!e){var o=document.querySelector("ins.adsbygoogle");o&&(e=!0,t&&t.disconnect(),o.setAttribute("data-ad-status","filled"),setTimeout(function(){o.setAttribute("data-adsbygoogle-status","done")},1e3))}}o(),e||(t=new MutationObserver(o)).observe(document,{childList:!0,subtree:!0})}();
```

